#!/usr/bin/env python3
from pathlib import Path
import html
import json
import re

ROOT = Path(__file__).resolve().parents[1]
E = html.escape
cards = json.loads((ROOT / "data/cards.json").read_text(encoding="utf-8"))["cards"]
sections = json.loads((ROOT / "data/sections.json").read_text(encoding="utf-8"))
labels = {"sections": "三十二分与全文", "pronunciation": "注音", "translations": "翻译", "allusions": "典故与语境", "idioms": "术语名句", "memory": "背诵方法"}
route = [s["title"] for s in sections]

body = []
for c in cards:
    fields = []
    for f in c["fields"]:
        fields.append(f'<h3>{E(f["label"])}</h3><p>{E(f["text"])}</p>')
    if c.get("image"):
        image = "../" + c["image"]
        fields.append(f'<figure><img loading="lazy" src="{E(image)}" alt="记忆类比插画"><figcaption>仅作教学类比，不是经文历史事件或宗教实相图。</figcaption></figure>')
    body.append(f'''<article class="study-card" id="{c['id']}" data-category="{c['category']}" data-section="{c['section']}">
<div class="eyebrow">{E(labels.get(c['category'], c['category']))} · {E(c['id'].upper())}</div>
<h2>{E(c['title'])}</h2><p class="front">{E(c['front'])}</p>
<details><summary>展开理解与记忆提示</summary><div class="answer">{''.join(fields)}</div></details>
<footer><button class="learned" type="button" data-id="{E(c['id'])}" aria-pressed="false">标为已学</button><a href="../{E(c['png'])}">PNG 长卡</a><a href="../{E(c['html'])}">大字卡</a><a href="../{E(c['markdown'])}">Markdown</a></footer></article>''')

route_html = "".join(f'<li><a class="route-link" href="#s{i+1:02}" data-go="s{i+1:02}"><span>{i+1:02d}</span>{E(t)}</a></li>' for i, t in enumerate(route))
cat_opts = "".join(f'<option value="{k}">{E(v)}</option>' for k, v in labels.items())
page = f'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>金刚经 · 一分一分，慢慢读</title><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script></head><body>
<a class="skip" href="#library">跳到学习卡</a><header class="hero"><div class="hero-copy"><p class="eyebrow">鸠摩罗什译通行本 · 全文学习 · v0.1.0-preview</p><h1>金刚般若<br>波罗蜜经</h1><p class="lead">一分一分，慢慢读。</p><p>先回到法会现场，再看无住、离相与如如不动。今天记住一段，就可以合上。</p><a class="start" href="#library">开始今天的一分</a></div><img src="../assets/images/boat-crossing.png" width="1536" height="1024" alt="一叶小舟驶向远岸，作为无住渡行的记忆提示"></header>
<main><section class="route" aria-label="三十二分路线"><h2>从一场乞食法会，读到如如不动。</h2><ol>{route_html}</ol><p class="muted">路线：法会与发心 → 无住布施 → 离相见如来 → 受持传法 → 无所得与无我 → 如如不动。正文 5,179 字；三十二分标题是后世学习导航。</p></section>
<section class="desk" id="library"><div class="desk-title"><h2>我的学习卡</h2><a href="guide.html">伴读、问答与概念笔记</a></div><div class="controls"><label>内容<select id="category">{cat_opts}<option value="all">全部</option></select></label><label class="search">找原句、术语或分名<input id="search" type="search" placeholder="例如：无住、歌利王、梦幻泡影" autocomplete="off"></label><label class="check"><input id="review" type="checkbox">只看已学过</label><button id="gentle" type="button" aria-pressed="false">今天睡得不好</button><label>字号<select id="size"><option value="20">舒适</option><option value="24">更大</option><option value="28">最大</option></select></label></div><p id="gentle-note" class="gentle" hidden>今天只复习，不学新分。挑一句熟悉的读一遍，三分钟内结束；也可以休息。已自动显示已学卡片。</p><p id="count" role="status" aria-live="polite"></p><p id="storage-note" class="muted">“已学”只保存在当前浏览器，不上传。</p><p id="empty" hidden>暂时没有匹配卡片。可以换一个词，或关闭“只看已学过”。今天休息也可以。</p><noscript>浏览器未启用脚本：下面仍可阅读全文和展开答案，筛选与已学记录不可用。</noscript><div class="cards">{''.join(body)}</div></section>
<section class="finish"><h2>读后留一句话</h2><p>今天哪一个“相”被你过快地当成了全部？</p><label for="reflection">写给自己，不必有标准答案</label><textarea id="reflection" rows="4" placeholder="我读到……时，想到……"></textarea><p class="muted" id="reflection-status">仅保存在本浏览器；也可抄到自己的本子。</p><p><a href="../content/full-text.md">全文原文</a> · <a href="../assets/cards/classic.html">彩色逐字注解</a> · <a href="../assets/cards/classic.png">全文注解长图</a> · <a href="../assets/cards/classic-pages.md">手机分片版</a> · <a href="../README.md">底本与异文</a> · <a href="../data/cards.json">卡片 JSON</a></p></section></main><footer class="site-footer">本项目编注与插画 · 姚秦鸠摩罗什译传统题署 · LJG 技能方法与模板署名见 README。私人学习初稿，可持续修订。</footer></body></html>'''
(ROOT / "preview/index.html").write_text(page, encoding="utf-8")

